namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Description = "A simple yet delicious pizza with fresh mozzarella and basil.", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil." },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Description = "Tender chicken in a creamy spiced tomato sauce.", Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nOnion\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or pan-fry chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomatoes and simmer 15 minutes.\n5. Stir in cream and spices.\n6. Add chicken and simmer 10 minutes." },
        new Recipe { Id = 3, Title = "Chocolate Lava Cake", Category = "Desserts", Description = "Rich chocolate cake with a molten center.", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Preheat oven to 425°F (220°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold chocolate mixture into eggs.\n5. Add flour and vanilla.\n6. Pour into greased ramekins.\n7. Bake 12-14 minutes until edges are set." },
        new Recipe { Id = 4, Title = "Caesar Salad", Category = "Salads", Description = "Crisp romaine with homemade Caesar dressing.", Ingredients = "Romaine lettuce\nParmesan cheese\nCroutons\nAnchovies\nGarlic\nLemon juice\nOlive oil\nEgg yolk\nDijon mustard", Steps = "1. Blend anchovies, garlic, lemon juice, egg yolk, and mustard.\n2. Slowly drizzle in olive oil to emulsify.\n3. Tear romaine into bite-sized pieces.\n4. Toss lettuce with dressing.\n5. Top with shaved Parmesan and croutons." },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Description = "Seasoned ground beef in warm tortillas.", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings." },
        new Recipe { Id = 6, Title = "Pad Thai", Category = "Asian", Description = "Stir-fried rice noodles with shrimp and tamarind sauce.", Ingredients = "Rice noodles\nShrimp\nEggs\nBean sprouts\nGreen onions\nPeanuts\nTamarind paste\nFish sauce\nSugar\nLime", Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Mix tamarind paste, fish sauce, and sugar for sauce.\n3. Stir-fry shrimp until pink, set aside.\n4. Scramble eggs in the wok.\n5. Add noodles and sauce, toss until coated.\n6. Add shrimp, bean sprouts, and green onions.\n7. Serve with peanuts and lime wedges." },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<RecipeCategory> GetCategories() => new()
    {
        new RecipeCategory { Name = "Italian", Description = "Pasta, pizza, and Mediterranean flavors", Icon = "🍕" },
        new RecipeCategory { Name = "Indian", Description = "Rich curries and aromatic spices", Icon = "🍛" },
        new RecipeCategory { Name = "Mexican", Description = "Bold flavors with fresh ingredients", Icon = "🌮" },
        new RecipeCategory { Name = "Asian", Description = "Stir-fries, noodles, and umami", Icon = "🍜" },
        new RecipeCategory { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" },
        new RecipeCategory { Name = "Salads", Description = "Fresh and healthy options", Icon = "🥗" },
    };

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();
        _ratings[recipeId].Add(stars);
    }

    public (double Average, int Count) GetRating(int recipeId)
    {
        if (!_ratings.ContainsKey(recipeId) || _ratings[recipeId].Count == 0)
            return (0, 0);
        var ratings = _ratings[recipeId];
        return (ratings.Average(), ratings.Count);
    }
}
"}

